package dev.aether.modules.inventorymanager

import dev.aether.config.AetherConfig
import dev.aether.macro.MacroState
import dev.aether.macro.MacroStateManager
import dev.aether.macro.MacroWorkerThread
import dev.aether.modules.gear.helpers.LoadoutManager
import dev.aether.modules.pest.PestManager
import dev.aether.modules.pest.helpers.PestPrepSwapManager
import dev.aether.util.ClientUtils
import net.minecraft.client.Minecraft
import net.minecraft.client.gui.screens.inventory.AbstractContainerScreen
import net.minecraft.world.inventory.ContainerInput
import net.minecraft.world.inventory.Slot
import net.minecraft.world.item.ItemStack

class AutoSellManager private constructor(){companion object{
 @JvmField @Volatile var isSelling=false
 @JvmField @Volatile var isPreparingToSell=false
 @JvmField @Volatile var isTriggeredBeforeVisitors=false
 @Volatile private var cancelRequested=false
 private var visitorResumeIntent=true
 private var wasRunningBeforeSell=false
 private var wasTriggeredManually=false
 private var thresholdMetStartTime=0L
 @Volatile private var interactionTime=0L
 @Volatile private var awaitingFirstGuiClick=false
 private var lastSellTime=0L
 private const val SELL_COOLDOWN_MS=30000L
 @JvmStatic fun reset(){cancelRequested=false;isSelling=false;isPreparingToSell=false;isTriggeredBeforeVisitors=false;wasRunningBeforeSell=false;wasTriggeredManually=false;thresholdMetStartTime=0;interactionTime=0;awaitingFirstGuiClick=false;lastSellTime=0}
 @JvmStatic fun cancel(client:Minecraft?){val active=isSelling||isPreparingToSell||isTriggeredBeforeVisitors;cancelRequested=true;isSelling=false;isPreparingToSell=false;isTriggeredBeforeVisitors=false;thresholdMetStartTime=0;awaitingFirstGuiClick=false;interactionTime=0;if(client!=null&&active)ClientUtils.closeGui(client)}
 @JvmStatic fun handleNpcCoinLimit(client:Minecraft?){val resume=MacroStateManager.getCurrentState()==MacroState.State.AUTOSELLING&&wasRunningBeforeSell&&!wasTriggeredManually;cancel(client);AetherConfig.AUTO_SELL.set(false);AetherConfig.save();if(MacroStateManager.getCurrentState()==MacroState.State.AUTOSELLING){if(resume){MacroStateManager.setCurrentState(MacroState.State.FARMING);val c=client;if(c!=null)c.execute{dev.aether.macro.farming.FarmingMacroManager.enable(c,dev.aether.macro.farming.FarmingMacroManager.createMacroFromConfig())}}else MacroStateManager.setCurrentState(MacroState.State.OFF)};ClientUtils.sendMessage("§cNPC shop coin limit reached. AutoSell disabled.",false)}
 private fun shouldAbort()=cancelRequested||MacroWorkerThread.getInstance().isCancelled()
 @JvmStatic fun getInventoryFullnessRatio(client:Minecraft):Double{val player=client.player?:return 0.0;var empty=0;for(i in 0 until 36){val stack=player.inventory.getItem(i);if(stack==null||stack.isEmpty)empty++};return ((36-empty)/36.0)*100.0}
 @JvmStatic fun getThresholdMetElapsedMs()=if(thresholdMetStartTime==0L)0L else maxOf(0L,System.currentTimeMillis()-thresholdMetStartTime)
 @JvmStatic fun getSellCooldownRemainingMs()=maxOf(0L,SELL_COOLDOWN_MS-(System.currentTimeMillis()-lastSellTime))
 @JvmStatic fun checkBeforeVisitors(client:Minecraft,force:Boolean,resumeAfter:Boolean):Boolean {if(!AetherConfig.AUTO_SELL_BEFORE_VISITORS.get())return false;visitorResumeIntent=resumeAfter;if(System.currentTimeMillis()-lastSellTime<SELL_COOLDOWN_MS){ClientUtils.sendDebugMessage("checkBeforeVisitors: Cooldown active (${SELL_COOLDOWN_MS-(System.currentTimeMillis()-lastSellTime)}ms left)");return false};ClientUtils.sendDebugMessage("Checking inventory for AutoSell before visitors...");if(LoadoutManager.isSwappingLoadout||GeorgeManager.isSelling||JunkManager.isDropping)return false;val ratio=getInventoryFullnessRatio(client);if(force||ratio>=AetherConfig.AUTO_SELL_THRESHOLD.get()){ClientUtils.sendDebugMessage((if(force)"Forced AutoSell" else "AutoSell threshold met (${String.format("%.1f",ratio)}%)")+", triggering before visitors...");if(Thread.currentThread().name=="aether-worker")runSellSequenceSync(client,true,false,true)else{isTriggeredBeforeVisitors=true;triggerSell(client,true,false)};return true}else ClientUtils.sendDebugMessage("checkBeforeVisitors: Threshold not met (${String.format("%.1f",ratio)}% < ${AetherConfig.AUTO_SELL_THRESHOLD.get()}%)");return false}
 @JvmStatic fun checkBeforePestTraps(client:Minecraft,force:Boolean,resumeAfter:Boolean):Boolean{if(!AetherConfig.AUTO_SELL_BEFORE_PEST_TRAPS.get())return false;visitorResumeIntent=resumeAfter;if(System.currentTimeMillis()-lastSellTime<SELL_COOLDOWN_MS){ClientUtils.sendDebugMessage("checkBeforePestTraps: Cooldown active (${SELL_COOLDOWN_MS-(System.currentTimeMillis()-lastSellTime)}ms left)");return false};ClientUtils.sendDebugMessage("Checking inventory for AutoSell before pest traps...");if(LoadoutManager.isSwappingLoadout||GeorgeManager.isSelling||JunkManager.isDropping)return false;val ratio=getInventoryFullnessRatio(client);if(force||ratio>=AetherConfig.AUTO_SELL_THRESHOLD.get()){ClientUtils.sendDebugMessage((if(force)"Forced AutoSell" else "AutoSell threshold met (${String.format("%.1f",ratio)}%)")+", triggering before pest traps...");if(!client.isSameThread)runSellSequenceSync(client,true,false,true)else{isTriggeredBeforeVisitors=true;triggerSell(client,true,false)};return true}else ClientUtils.sendDebugMessage("checkBeforePestTraps: Threshold not met (${String.format("%.1f",ratio)}% < ${AetherConfig.AUTO_SELL_THRESHOLD.get()}%)");return false}
 private fun isPriorityEventActive(client:Minecraft,ignoreVisitors:Boolean)=LoadoutManager.isSwappingLoadout||PestManager.isCleaningInProgress()||PestPrepSwapManager.isPrepSwapping()||(!ignoreVisitors&&dev.aether.modules.visitor.VisitorsMacro.isRunning)||BookCombineManager.isCombining||BookCombineManager.isPreparingToCombine||GeorgeManager.isSelling||GeorgeManager.isPreparingToSell||JunkManager.isDropping||JunkManager.isPreparingToDrop
 @JvmStatic fun update(){val client=Minecraft.getInstance();if(!AetherConfig.AUTO_SELL.get()||client.player==null){thresholdMetStartTime=0;return};if(System.currentTimeMillis()-lastSellTime<SELL_COOLDOWN_MS){thresholdMetStartTime=0;return};val bazaar=dev.aether.util.BazaarUtils.isSellingBazaar;if(isPreparingToSell||isSelling||bazaar){if(!isTriggeredBeforeVisitors&&isPriorityEventActive(client,true)){isPreparingToSell=false;isSelling=false;lastSellTime=System.currentTimeMillis();ClientUtils.sendMessage("§cAborting AutoSell due to priority event.",false);return};thresholdMetStartTime=0;if(isSelling&&client.gui.screen()==null){val elapsed=System.currentTimeMillis()-interactionTime;if(elapsed>2500&&elapsed<2700)ClientUtils.sendCommand("/boostercookie")else if(elapsed>5000){ClientUtils.sendDebugMessage("AutoSell GUI failed to open after 5s. Finishing...");finishSelling(client)}};return};if(isPriorityEventActive(client,false)){thresholdMetStartTime=0;return};if(MacroStateManager.getCurrentState()!=MacroState.State.FARMING){thresholdMetStartTime=0;return};val ratio=getInventoryFullnessRatio(client);if(ratio>=AetherConfig.AUTO_SELL_THRESHOLD.get()){if(thresholdMetStartTime==0L)thresholdMetStartTime=System.currentTimeMillis() else if(System.currentTimeMillis()-thresholdMetStartTime>=AetherConfig.AUTO_SELL_TIME.get()*1000L){triggerSell(client,false,false);thresholdMetStartTime=0}}else thresholdMetStartTime=0}
 @JvmStatic fun runSellSequenceSync(client:Minecraft,isBeforeVisitor:Boolean,isManual:Boolean,isNested:Boolean){cancelRequested=false;wasRunningBeforeSell=MacroStateManager.isMacroRunning();wasTriggeredManually=isManual;ClientUtils.sendMessage("§eAuto-selling inventory contents...",false);ClientUtils.forceReleaseKeys();isPreparingToSell=true;isSelling=false;try{if(shouldAbort())return;if(MacroStateManager.getCurrentState()==MacroState.State.FARMING&&!isNested){ClientUtils.sendDebugMessage("Disabling farming macro: Preparing AutoSell");client.execute{dev.aether.macro.farming.FarmingMacroManager.disable(client)}};MacroWorkerThread.sleep(500);if(shouldAbort())return;isPreparingToSell=false;val previous=MacroStateManager.getCurrentState();if(!isNested&&(wasRunningBeforeSell||isBeforeVisitor&&visitorResumeIntent)&&!isManual)MacroStateManager.setCurrentState(MacroState.State.AUTOSELLING);if(AetherConfig.AUTO_SELL_NPC.get()){isSelling=true;interactionTime=System.currentTimeMillis();awaitingFirstGuiClick=true;ClientUtils.closeGui(client);ClientUtils.sendCommand("/boostercookie");while(isSelling&&!shouldAbort()){MacroWorkerThread.sleep(100);if(System.currentTimeMillis()-interactionTime>30000){ClientUtils.sendDebugMessage("NPC Autosell timed out.");isSelling=false}}};if(!shouldAbort()&&AetherConfig.AUTO_SELL_BAZAAR.get()){ClientUtils.sendDebugMessage("Bazaar phase safety delay...");MacroWorkerThread.sleep(1000);ClientUtils.sendDebugMessage("Starting Bazaar Autosell phase...");try{dev.aether.util.BazaarUtils.executeInstantSell(client)}catch(e:Exception){ClientUtils.sendDebugMessage("Bazaar autosell failed.");e.printStackTrace()}};lastSellTime=System.currentTimeMillis();if(shouldAbort())return;if(isNested){MacroStateManager.setCurrentState(previous);ClientUtils.sendMessage("§aAuto-Sell finished. Resuming macro...",true)}else resumeAfterAutoSell(client)}catch(e:Exception){e.printStackTrace();if(!isNested&&!shouldAbort())resumeAfterAutoSell(client)}finally{isSelling=false;isPreparingToSell=false}}
 private fun triggerSell(client:Minecraft,isBeforeVisitor:Boolean,isManual:Boolean){cancelRequested=false;wasRunningBeforeSell=MacroStateManager.isMacroRunning();wasTriggeredManually=isManual;ClientUtils.sendMessage("§eAuto-selling inventory contents...",false);ClientUtils.forceReleaseKeys();isPreparingToSell=true;isSelling=false;MacroWorkerThread.getInstance().submit("AutoSell-Trigger"){runSellSequenceSync(client,isBeforeVisitor,isManual,false)}}
 private fun resumeAfterAutoSell(client:Minecraft){MacroWorkerThread.getInstance().submit("AutoSell-Finish"){MacroWorkerThread.sleep(500);if(shouldAbort())return@submit;if(ClientUtils.isInventoryScreenOpen()){ClientUtils.sendDebugMessage("AutoSell: closing a lingering container before resuming.");ClientUtils.closeGui(client)};if(MacroStateManager.getCurrentState()==MacroState.State.AUTOSELLING||isTriggeredBeforeVisitors){if(isTriggeredBeforeVisitors){isTriggeredBeforeVisitors=false;if(wasRunningBeforeSell&&visitorResumeIntent&&!wasTriggeredManually)MacroStateManager.setCurrentState(MacroState.State.FARMING)else if(!wasTriggeredManually)MacroStateManager.setCurrentState(MacroState.State.OFF);if(!shouldAbort()){if(dev.aether.modules.visitor.VisitorManager.shouldSkipVisitorsDuringJacobsContest(client,true)){if(wasRunningBeforeSell&&visitorResumeIntent&&!wasTriggeredManually)client.execute{dev.aether.macro.farming.FarmingMacroManager.enable(client,dev.aether.macro.farming.FarmingMacroManager.createMacroFromConfig())}else client.execute{dev.aether.modules.visitor.VisitorsMacro.start(client,!visitorResumeIntent||wasTriggeredManually)}}}else if(wasRunningBeforeSell&&!wasTriggeredManually){MacroStateManager.setCurrentState(MacroState.State.FARMING);client.execute{dev.aether.macro.farming.FarmingMacroManager.enable(client,dev.aether.macro.farming.FarmingMacroManager.createMacroFromConfig())}}else if(!wasTriggeredManually)MacroStateManager.setCurrentState(MacroState.State.OFF)}}};if(!shouldAbort()&&client.player!=null)ClientUtils.sendMessage("§aAuto-Sell finished. Resuming tasks...",true)}
 @JvmStatic fun handleMenu(client:Minecraft,screen:AbstractContainerScreen<*>?){if(!isSelling||screen==null||screen.menu==null||screen.title==null||client.player==null||client.gameMode==null)return;val now=System.currentTimeMillis();if(now-interactionTime<ClientUtils.getGuiClickDelayMs(awaitingFirstGuiClick))return;val title=screen.title.string.replace(Regex("(?i)\u00A7."),"").lowercase();if(!title.contains("booster cookie"))return;val slots=screen.menu.slots;for(i in slots.size-36 until slots.size){val slot:Slot=slots[i];if(!slot.hasItem())continue;val name=slot.item.hoverName.string.replace(Regex("(?i)\u00A7."),"").lowercase();if(AetherConfig.AUTO_SELL_ITEMS.get().any{it.isNotBlank()&&name.contains(it.lowercase())}){interactionTime=now;awaitingFirstGuiClick=false;ClientUtils.performSlotClick(screen,i,0,ContainerInput.QUICK_MOVE);return}};finishSelling(client)}
 @JvmStatic fun manualTrigger(client:Minecraft){if(client.player!=null)ClientUtils.sendMessage("§eManually triggering AutoSell...",false);triggerSell(client,false,true)}
 @JvmStatic fun finishSelling(client:Minecraft){ClientUtils.closeGui(client);isSelling=false}
}}
